{"command": "cd /home/jinsc/Desktop_My/work/my_work/sifli/01_hw && python3 - <<'EOF'
import sqlite3, json
c=sqlite3.connect('file:speedometer.eprj2?mode=ro', uri=True)
c.row_factory=sqlite3.Row
for t in ['projects','boards','documents','branches','project_structures']:
    print('='*20, t)
    try:
        cur=c.execute(f'select * from {t} limit 50')
        cols=[d[0] for d in cur.description]
        print('cols:',cols)
        for r in cur.fetchall():
            d=dict(r)
            # truncate large blobs
            out={k:(str(v)[:160] if v is not None else None) for k,v in d.items()}
            print(json.dumps(out,ensure_ascii=False))
    except Exception as e:
        print('ERR',e)
EOF", "description": "Read projects/boards/documents tables"}

